module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg a_sign, b_sign, z_sign;
reg [49:0] product;
reg guard_bit, round_bit, sticky;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        counter <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        z_mantissa <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        z_exponent <= 0;
        a_sign <= 0;
        b_sign <= 0;
        z_sign <= 0;
        product <= 0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky <= 0;
        z <= 0;
    end else begin
        case (counter)
            0: begin
                a_mantissa <= {a[22:0], 8'b0};
                b_mantissa <= {b[22:0], 8'b0};
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_sign <= a[31];
                b_sign <= b[31];
                counter <= 1;
            end
            1: begin
                if ((a_exponent == 8'hFF && a_mantissa != 0) || (b_exponent == 8'hFF && b_mantissa != 0)) begin
                    z <= 0;
                end else begin
                    product = a_mantissa * b_mantissa;
                    guard_bit = product[49];
                    round_bit = product[48];
                    sticky = product[47] | product[46] | product[45] | product[44] | product[43] | product[42] | product[41] | product[40];
                    z_mantissa = product[48:15];
                    z_exponent = a_exponent + b_exponent - 8'hFE;
                    z_sign = a_sign ^ b_sign;
                    if (z_exponent > 8'hFF) begin
                        z_exponent = 8'hFF;
                        z_mantissa = 23'hFFFFF;
                    end else if (z_exponent < 8'h00) begin
                        z_exponent = 8'h00;
                        z_mantissa = 23'h00001;
                    end else begin
                        while (z_mantissa[23] == 1'b0) begin
                            z_mantissa = {z_mantissa[22:0], 1'b0};
                            z_exponent = z_exponent - 1;
                        end
                    end
                    z = {z_sign, z_exponent, z_mantissa};
                end
                counter <= 0;
            end
        endcase
    end
end

endmodule
